// Emit the bench runner's exact wire enums and records. Its partial views of
// replies from older hosts remain in the runner.
export function acceptanceBindings(app, enums) {
  const lines = [
    '# Generated by cargo xtask codegen from Rust. Do not edit.',
    'from enum import StrEnum',
    'from typing import Literal, NotRequired, TypedDict',
  ];
  for (const [name, values] of Object.entries(enums)) {
    lines.push('', '', `class ${name}(StrEnum):`);
    for (const value of values)
      lines.push(`    ${value.toUpperCase()} = '${value}'`);
  }
  for (const [name, schema] of Object.entries({
    Span: app.Span,
    CaptureMode: app.Mode,
    LightingControl: app.LightingControl,
  })) {
    lines.push('', '', `class ${name}(TypedDict):`);
    for (const [field, property] of Object.entries(schema.properties)) {
      const type = fieldType(app, property);
      const annotation = schema.required.includes(field)
        ? type
        : `NotRequired[${type}]`;
      lines.push(`    ${field}: ${annotation}`);
    }
  }
  return lines.join('\n') + '\n';
}

function fieldType(schemas, property) {
  if (property.type === 'integer') return 'int';
  if (property.type === 'boolean') return 'bool';
  if (property.$ref) {
    const name = property.$ref.split('/').at(-1);
    const values = schemas[name].enum;
    if (values)
      return `Literal[${values.map((value) => `'${value}'`).join(', ')}]`;
    return name;
  }
  throw new Error(`Unsupported acceptance field: ${JSON.stringify(property)}`);
}
